from typing import List


class Solution:
    def longestWord(self, words: List[str]) -> str:
        seen = set(words)
        best = ""
        for word in words:
            valid = True
            for i in range(1, len(word) + 1):
                if word[:i] not in seen:
                    valid = False
                    break
            if valid and (len(word) > len(best) or (len(word) == len(best) and word < best)):
                best = word
        return best

