from typing import List


class Solution:
    def longestWord(self, words: List[str]) -> str:
        buildable = {""}
        best = ""
        for word in sorted(words):
            # A word is buildable if removing its last char is buildable.
            if word[:-1] in buildable:
                buildable.add(word)
                if len(word) > len(best):
                    best = word
        return best

